PLANS={544: ('gluant marin', '2000', 180, 'Gluant marin : variante marine du gluant, distinct du coquigluant voisin. Correspondance JP complète avec la DS ; singulier@4 seul, articles/pluriel/balises DS non injectés. Largeur non augmentée. Accords contextuels naturels à auditer.'), 545: ('coquigluant', '2000', 91, 'Coquigluant : gluant à coquille, pas un escargot générique. Correspondance JP complète avec la DS ; singulier@4 seul, articles/pluriel/balises DS non injectés. Largeur non augmentée. Accords contextuels naturels à auditer.'), 546: ('aquapode', '2000', 173, 'Aquapode : espèceシーフラワー, distincte des autres gastéropodes. Correspondance JP complète avec la DS ; singulier@4 seul, articles/pluriel/balises DS non injectés. Largeur non augmentée. Accords contextuels naturels à auditer.'), 548: ('dingopode', '2000', 18, 'Dingopode : espèceテールイーター ; nom officiel DS conservé. Correspondance JP complète avec la DS ; singulier@4 seul, articles/pluriel/balises DS non injectés. Largeur non augmentée. Accords contextuels naturels à auditer.'), 550: ('salchodron', '2000', 187, 'Salchodron : アクアハンター, distinct du chodronmagik549 à commande de ligne. Correspondance JP complète avec la DS ; singulier@4 seul, articles/pluriel/balises DS non injectés. Largeur non augmentée. Accords contextuels naturels à auditer.'), 555: ('toxinavet', '2000', 69, 'Toxinavet : carotte empoisonnée, distincte de la povkarotte554. Correspondance JP complète avec la DS ; singulier@4 seul, articles/pluriel/balises DS non injectés. Largeur non augmentée. Accords contextuels naturels à auditer.'), 559: ('gluante', '2000', 20, 'Gluante : varianteスライムベス, distincte du gluant standard et du gluant moucheté. Correspondance JP complète avec la DS ; singulier@4 seul, articles/pluriel/balises DS non injectés. Largeur non augmentée. Accords contextuels naturels à auditer.'), 572: ('méduse', '2000', 186, 'Méduse : ennemiしびれくらげ paralysant, pas un bateau malgré ancien Man O’ War. Correspondance JP complète avec la DS ; singulier@4 seul, articles/pluriel/balises DS non injectés. Largeur non augmentée. Accords contextuels naturels à auditer.'), 578: ('iguaraptor', '2000', 88, 'Iguaraptor : lézardメダパニ, distinct de l’iguanosaure577. Correspondance JP complète avec la DS ; singulier@4 seul, articles/pluriel/balises DS non injectés. Largeur non augmentée. Accords contextuels naturels à auditer.'), 584: ('ombre', '2000', 30, 'Ombre : シャドー, distincte du spectre585. Correspondance JP complète avec la DS ; singulier@4 seul, articles/pluriel/balises DS non injectés. Largeur non augmentée. Accords contextuels naturels à auditer.'), 585: ('spectre', '2000', 149, 'Spectre : ホロゴースト, distinct de l’ombre584. Correspondance JP complète avec la DS ; singulier@4 seul, articles/pluriel/balises DS non injectés. Largeur non augmentée. Accords contextuels naturels à auditer.'), 586: ('Milo', '2000', 235, 'Milo : bossズイカク, associé à Kapout587 ; nom propre DS complet. Correspondance JP complète avec la DS ; singulier@4 seul, articles/pluriel/balises DS non injectés. Largeur non augmentée. Accords contextuels naturels à auditer.'), 587: ('Kapout', '2000', 236, 'Kapout : bossショウカク, associé à Milo586 ; nom propre DS complet. Correspondance JP complète avec la DS ; singulier@4 seul, articles/pluriel/balises DS non injectés. Largeur non augmentée. Accords contextuels naturels à auditer.'), 589: ('limassif', '2000', 64, 'Limassif : stadeスーパーテンツク, distinct du limasson588 et limastard590. Correspondance JP complète avec la DS ; singulier@4 seul, articles/pluriel/balises DS non injectés. Largeur non augmentée. Accords contextuels naturels à auditer.'), 590: ('limastard', '2000', 142, 'Limastard : stadeラストテンツク, distinct de limassif589. Correspondance JP complète avec la DS ; singulier@4 seul, articles/pluriel/balises DS non injectés. Largeur non augmentée. Accords contextuels naturels à auditer.'), 592: ('mouillebave', '2000', 175, 'Mouillebave : おばけうみうし, famille des bisebaves/lèchebaves. Correspondance JP complète avec la DS ; singulier@4 seul, articles/pluriel/balises DS non injectés. Largeur non augmentée. Accords contextuels naturels à auditer.'), 595: ('porcinglé', '2000', 135, 'Porcinglé : バーサクオーク, distinct du porcelaid594. Correspondance JP complète avec la DS ; singulier@4 seul, articles/pluriel/balises DS non injectés. Largeur non augmentée. Accords contextuels naturels à auditer.'), 596: ('rétroterreur', '2000', 51, 'Rétroterreur : miroir démoniaqueあくまのカガミ, distinct des deux autres miroirs597/598. Correspondance JP complète avec la DS ; singulier@4 seul, articles/pluriel/balises DS non injectés. Largeur non augmentée. Accords contextuels naturels à auditer.'), 598: ('refléfatal', '2000', 112, 'Refléfatal : miroir mauditのろいのカガミ, distinct du rétroterreur596. Correspondance JP complète avec la DS ; singulier@4 seul, articles/pluriel/balises DS non injectés. Largeur non augmentée. Accords contextuels naturels à auditer.'), 600: ('toxiguêpe', '2000', 77, 'Toxiguêpe : ポイズンキラー, distinct du frelon de l’enfer599. Correspondance JP complète avec la DS ; singulier@4 seul, articles/pluriel/balises DS non injectés. Largeur non augmentée. Accords contextuels naturels à auditer.'), 601: ('monte-gluant', '2000', 22, 'Monte-gluant : スライムナイト, distinct de la variante métallique602. Correspondance JP complète avec la DS ; singulier@4 seul, articles/pluriel/balises DS non injectés. Largeur non augmentée. Accords contextuels naturels à auditer.'), 604: ('cupitron', '2000', 54, 'Cupitron : ドッグスナイパー, distinct du cupimonstre603. Correspondance JP complète avec la DS ; singulier@4 seul, articles/pluriel/balises DS non injectés. Largeur non augmentée. Accords contextuels naturels à auditer.'), 610: ('flammulus', '2000', 11, 'Flammulus : ギズモ, famille gaz nuageux ; distinct des variantes chaud/froid611/612. Correspondance JP complète avec la DS ; singulier@4 seul, articles/pluriel/balises DS non injectés. Largeur non augmentée. Accords contextuels naturels à auditer.'), 611: ('cramulus', '2000', 45, 'Cramulus : ヒートギズモ, variante chaude du flammulus. Correspondance JP complète avec la DS ; singulier@4 seul, articles/pluriel/balises DS non injectés. Largeur non augmentée. Accords contextuels naturels à auditer.'), 612: ('brumulus', '2000', 118, 'Brumulus : フロストギズモ, variante froide du flammulus. Correspondance JP complète avec la DS ; singulier@4 seul, articles/pluriel/balises DS non injectés. Largeur non augmentée. Accords contextuels naturels à auditer.'), 614: ('mâchosaure', '2000', 103, 'Mâchosaure : キングイーター, distinct du bâillosaure613. Correspondance JP complète avec la DS ; singulier@4 seul, articles/pluriel/balises DS non injectés. Largeur non augmentée. Accords contextuels naturels à auditer.'), 619: ('salgouille', '2000', 86, 'Salgouille : ダークゴイル, distinct des variantes minigouille618/malgouille620. Correspondance JP complète avec la DS ; singulier@4 seul, articles/pluriel/balises DS non injectés. Largeur non augmentée. Accords contextuels naturels à auditer.'), 620: ('malgouille', '2000', 141, 'Malgouille : キラーバット, distinct de salgouille619. Correspondance JP complète avec la DS ; singulier@4 seul, articles/pluriel/balises DS non injectés. Largeur non augmentée. Accords contextuels naturels à auditer.')}
